ossible === true || item.categorie === 'spam';\\n\\nreturn [{ json: { ...item, targetFolder, markAsRead } }];"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1344,288],"id":"f1a1b111-0000-4000-8000-000000000020","name":"Déterminer dossier cible"},{"parameters":{"authentication":"imapThisNode","resource":"email","operation":"moveEmail","sourceMailbox":{"__rl":true,"mode":"path","value":"INBOX"},"emailUid":"={{ $('Email Trigger (IMAP)').item.json.attributes.uid }}","destinationMailbox":{"__rl":true,"mode":"path","value":"={{ $('Déterminer dossier cible').item.json.targetFolder }}"}},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[1568,288],"id":"f1a1b111-0000-4000-8000-000000000021","name":"Déplacer le mail","credentials":{"imapApi":{"id":"7D7EF7hYzLreslfS","name":"IMAP Move - v.caufriez@ebanista.fr"}}},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f1a1b111-0000-4000-8000-00000000f003","leftValue":"={{ $json.markAsRead }}","rightValue":"","operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1568,200],"id":"f1a1b111-0000-4000-8000-000000000022","name":"Faut-il marquer lu ?"},{"parameters":{"authentication":"imapThisNode","resource":"email","operation":"setEmailFlags","mailboxPath":{"__rl":true,"mode":"path","value":"INBOX"},"emailUid":"={{ $('Email Trigger (IMAP)').item.json.attributes.uid }}","flags":{"\\\\Seen":true}},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[1792,144],"id":"f1a1b111-0000-4000-8000-000000000023","name":"Marquer comme lu","credentials":{"imapApi":{"id":"7D7EF7hYzLreslfS","name":"IMAP Move - v.caufriez@ebanista.fr"}}},{"parameters":{"amount":1},"type":"n8n-nodes-base.wait","typeVersion":1.1,"position":[1792,144],"id":"f1a1b111-0000-4000-8000-000000000024","name":"Attendre 8s","webhookId":"a0113614-411e-4451-8f6e-24805da6f08